package com.example.rokidgeminisecretary;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;
final class ExperienceDialog {
 final MainActivity owner;final ReliabilityDialog ui;final MaintenanceDialog maintenance;
 ExperienceDialog(MainActivity c){owner=c;ui=new ReliabilityDialog(c);maintenance=new MaintenanceDialog(c);}
 static View navigation(MainActivity c){LinearLayout row=new LinearLayout(c);String[] titles={"話す","記録","要対応","設定"};for(int i=0;i<titles.length;i++){final int index=i;Button b=new Button(c);b.setText(titles[i]);b.setContentDescription(titles[i]+"を開く");b.setTextSize(14);b.setMinWidth(0);b.setPadding(0,4,0,4);b.setMinHeight((int)(48*c.getResources().getDisplayMetrics().density));b.setOnClickListener(v->{ExperienceDialog d=new ExperienceDialog(c);switch(index){case 0:c.homeSpeak();break;case 1:d.records();break;case 2:d.attention();break;default:d.settings();}});row.addView(b,new LinearLayout.LayoutParams(0,-2,1));}return row;}
 void records(){new AlertDialog.Builder(owner).setTitle("記録を見る").setItems(new String[]{"すべての記録を検索","写真","会議・文字起こし","メモ・ごみ箱","会議タスク","重複・似た記録の候補","利用量・料金の目安","バックアップ・復元","生成した画像・動画"},(d,n)->{switch(n){case 0:maintenance.search();break;case 1:owner.startActivity(new Intent(owner,RecorderGalleryActivity.class));break;case 2:maintenance.meetings();break;case 3:ui.notes();break;case 4:maintenance.tasks();break;case 5:duplicates();break;case 6:usage();break;case 7:new MaintenanceBackupUi(owner).show();break;default:owner.openGeneratedRecords();}}).setNegativeButton("閉じる",null).show();}
 void attention(){ui.get("maintenance-attention",v->{LinearLayout b=ui.box();JSONArray rows=v.optJSONArray("items"),issues=v.optJSONArray("issues");ui.text(b,"要対応 "+rows.length()+"件");if(rows.length()==0)ui.text(b,issues!=null&&issues.length()>0?"取得できた範囲では要対応項目はありません。未確認の分類があります。":"現在、要対応項目はありません。");if(issues!=null&&issues.length()>0){StringBuilder missing=new StringBuilder();for(int i=0;i<issues.length();i++){if(i>0)missing.append("、");missing.append(issues.optString(i));}ui.text(b,"未確認の分類："+missing);}ui.button(b,"確認範囲・詳細",()->{LinearLayout detail=ui.box();ui.text(detail,v.optString("scope"));ui.text(detail,"自動再送・削除・予定登録はしません。取得できない分類："+(issues==null||issues.length()==0?"なし":issues.toString()));ui.display("要対応の確認範囲",detail);});for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);ui.text(b,row.optString("title")+"\n"+row.optString("reason"));ui.button(b,"この項目を確認",()->route(row.optString("route")));}ui.button(b,"一覧を更新",this::attention);ui.display("要対応",b);});}
 void route(String route){switch(route){case "updates":LokiUpdateDialog.show(owner);break;case "pronunciation":PronunciationDialog.show(owner);break;case "queue":QueuedConversationDialog.show(owner,()->owner.openConversationRecovery());break;case "jobs":ui.jobs();break;case "tasks":maintenance.tasks();break;case "storage":ui.storage();break;case "inbox":ui.inbox();break;case "schedule":maintenance.schedule();break;case "memory":ui.memory();break;case "volume":ui.profiles();break;case "notices":ui.notices();break;case "display":maintenance.display();break;case "backup":new MaintenanceBackupUi(owner).show();break;case "transfer":maintenance.schedule();break;case "capacity":maintenance.capacity();break;case "connections":maintenance.diagnosis();break;case "web":ui.sessions();break;case "maintenance":maintenance.show();break;case "usage":usage();break;case "duplicates":duplicates();break;default:owner.homeAdvanced();}}
 void settings(){LinearLayout b=ui.box();EditText query=ui.field(b,"設定を検索（例：音量・通知・保存）","",160);ui.button(b,"設定を検索",()->{query.clearFocus();android.view.inputmethod.InputMethodManager keyboard=(android.view.inputmethod.InputMethodManager)owner.getSystemService(Context.INPUT_METHOD_SERVICE);if(keyboard!=null)keyboard.hideSoftInputFromWindow(query.getWindowToken(),0);ui.get("maintenance-settings-search",ui.params("q",query.getText().toString()),v->{LinearLayout result=ui.box();JSONArray rows=v.optJSONArray("items");ui.text(result,"一致 "+rows.length()+"件。検索だけでは設定を変更しません。");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);ui.button(result,row.optString("title"),()->route(row.optString("route")));}ui.display("設定の検索結果",result);});});for(String[] item:new String[][]{{"updates","アプリ更新・更新前チェック"},{"pronunciation","メガネの読み上げ辞書・試聴"},{"queue","送信待ち・待ち時間"},{"volume","音量"},{"notices","通知"},{"display","文字・コントラスト"},{"backup","バックアップ・復元"},{"transfer","転送予約"},{"capacity","容量・保存期間"},{"connections","接続診断"},{"web","Web接続の権限"},{"maintenance","保守・更新前チェック"},{"advanced","その他の既存設定"}})ui.button(b,item[1],()->route(item[0]));ui.display("設定",b);}
 void editTask(JSONObject row){LinearLayout b=ui.box();ui.text(b,"出典："+row.optString("excerpt")+"\n元会議の参照は変更しません。本文・担当・期限を修正して保存してください。");EditText title=ui.field(b,"本文",row.optString("title"),800),person=ui.field(b,"担当（任意）",row.optString("assignee"),120),due=ui.field(b,"期限 YYYY-MM-DD（任意）",row.optString("due"),10);ui.button(b,"編集を保存",()->ui.work(()->MeetingTaskBoard.edit(owner,ui.with(ui.with(ui.with(ui.with(ui.with(ui.obj(),"id",row.getString("id")),"revision",row.getInt("revision")),"title",title.getText().toString()),"assignee",person.getText().toString()),"due",due.getText().toString())),saved->{LinearLayout result=ui.box();ui.text(result,"タスクを更新しました");ui.button(result,"この編集を元に戻す",()->ui.work(()->MeetingTaskBoard.edit(owner,ui.with(ui.with(ui.with(ui.with(ui.with(ui.obj(),"id",saved.getString("id")),"revision",saved.getInt("revision")),"title",row.getString("title")),"assignee",row.optString("assignee")),"due",row.optString("due"))),restored->maintenance.tasks()));ui.display("タスクの編集",result);}));JSONArray history=row.optJSONArray("history");for(int i=0;history!=null&&i<history.length();i++){JSONObject old=history.optJSONObject(i);ui.text(b,"履歴 "+(i+1)+"："+old.optString("title")+" / 担当 "+old.optString("assignee")+" / 期限 "+old.optString("due"));ui.button(b,"この履歴を入力欄へ戻す（未保存）",()->{title.setText(old.optString("title"));person.setText(old.optString("assignee"));due.setText(old.optString("due"));});}ui.button(b,"元の会議を開く",()->MeetingReviewDialog.show(owner,row.optString("meetingId")));ui.display("タスクの編集・履歴10世代",b);}
 static void openRecord(MainActivity c,JSONObject row){String type=row.optString("type");if(type.equals("photo")){try{c.startActivity(new Intent(c,RecorderGalleryActivity.class).putExtra("photoId",RecordAnchors.photoId(row.optString("id"))));}catch(Exception e){Toast.makeText(c,"写真の参照が不正です",Toast.LENGTH_LONG).show();}return;}if(type.equals("meeting")&&row.has("anchorMs")){MeetingReviewDialog.showAt(c,row.optString("id"),row.optLong("anchorMs"),true);return;}if(type.equals("task")){new ExperienceDialog(c).maintenance.tasks();return;}UnifiedRecordsDialog.open(c,row);}
 void duplicates(){ui.get("maintenance-duplicates",v->{LinearLayout b=ui.box();ui.text(b,v.optString("scope")+"\n似たメモは意味の異なる内容も含みます。両方を確認して選んでください。");JSONArray rows=v.optJSONArray("items");if(rows.length()==0)ui.text(b,"表示範囲で候補は見つかりませんでした");for(int i=0;i<rows.length();i++){JSONObject pair=rows.optJSONObject(i);if(pair.optString("type").equals("note")){ui.text(b,"残すメモ："+pair.optString("keepText")+"\n整理する候補："+pair.optString("removeText")+"\n文字類似度："+Math.round(pair.optDouble("similarity")*100)+"%");}else{ui.text(b,"同じ受領ハッシュを持つ写真の候補です。削除前にも実データを照合します");for(String key:new String[]{"keepId","removeId"})ui.button(b,key.equals("keepId")?"残す写真を開く":"整理候補の写真を開く",()->owner.startActivity(new Intent(owner,RecorderGalleryActivity.class).putExtra("photoId",pair.optString(key))));}ui.button(b,pair.optString("type").equals("note")?"候補のメモだけをごみ箱へ":"候補のスマホ写真だけを完全削除",()->ui.confirm(pair.optString("type").equals("note")?"表示した候補メモだけをごみ箱へ移動します。履歴画面から復元できます。":"表示した候補写真だけをスマホから完全削除します。復元できません。残す写真の実データも照合してから削除します。グラスとギャラリーは変更しません。",()->ui.work(()->DuplicateReview.cleanup(owner,pair),result->{LinearLayout done=ui.box();ui.text(done,result.optString("message"));JSONObject note=result.optJSONObject("note");if(note!=null)ui.button(done,"ごみ箱移動を元に戻す",()->ui.noteAction(note,"restore",null));ui.display("選んだ記録の整理",done);})));}ui.display("重複・似た記録の確認",b);});}
 void usage(){ui.get("maintenance-usage",v->{LinearLayout b=ui.box();ui.text(b,v.optString("scope"));JSONArray rows=v.optJSONArray("items");JSONObject rates=v.optJSONObject("rates");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);ui.text(b,row.optString("day")+" / "+row.optString("kind")+"\n送信試行 "+row.optInt("requests")+"件 / API利用量の報告あり "+row.optInt("reportedRequests")+"件\n入力バイト見積り "+row.optLong("inputBytesEstimate")+" / 入力トークンの報告 "+row.optInt("inputReportedRequests")+"件・計 "+row.optLong("inputTokens")+" / 出力トークンの報告 "+row.optInt("outputReportedRequests")+"件・計 "+row.optLong("outputTokens")+(row.has("tokenCostEstimate")?"\n指定単価によるトークン料金の一部見積り："+row.optDouble("tokenCostEstimate")+" "+rates.optString("currency"):"\n金額は未計算（単価未設定）"));}ui.text(b,"APIが返さない利用量は不明です。報告済みトークンだけの部分集計であり、0を無料や利用なしの意味にしません。以下の単価は全対象機能に一律で使う利用者指定値で、最新料金の取得はしません。");EditText input=ui.field(b,"入力100万トークンあたりの単価",rates.has("inputPerMillion")?""+rates.optDouble("inputPerMillion"):"",30),output=ui.field(b,"出力100万トークンあたりの単価",rates.has("outputPerMillion")?""+rates.optDouble("outputPerMillion"):"",30),currency=ui.field(b,"通貨 JPY / USD",rates.optString("currency","JPY"),3);ui.button(b,"見積り用の単価を保存",()->{try{ui.post("maintenance-usage-rates",ui.with(ui.with(ui.with(ui.obj(),"inputPerMillion",Double.parseDouble(input.getText().toString())),"outputPerMillion",Double.parseDouble(output.getText().toString())),"currency",currency.getText().toString().trim()));}catch(Exception e){ui.confirm("0以上の数値とJPYまたはUSDを入力してください",()->{});}});ui.display("利用量と料金の目安",b);});}
}
